+/* ─── Component functions ────────────────────────────────── */
+
+/**
+ * TextField — renders a labelled input with optional help/error text.
+ * Mirrors a React controlled-component signature but returns an HTML string.
+ */
+function TextField({ id, label, type = "text", required = false, helpText = null, autocomplete = "off" }) {
+  const describedByIds = [];
+  if (helpText) describedByIds.push(`${id}-help`);
+  describedByIds.push(`${id}-error`);
+
+  return `
+    <div class="form-field" data-field="${id}">
+      <label for="${id}" class="form-label">
+        ${escHtml(label)}
+        ${required
+          ? `<span class="required-mark" aria-hidden="true">*</span>`
+          : `<span class="optional-badge">(optional)</span>`}
+      </label>
+      ${helpText ? `<p id="${id}-help" class="form-help">${escHtml(helpText)}</p>` : ""}
+      <input
+        id="${id}"
+        name="${id}"
+        type="${type}"
+        class="form-input"
+        autocomplete="${autocomplete}"
+        aria-describedby="${describedByIds.join(" ")}"
+        ${required ? "required" : ""}
+      >
+      <p id="${id}-error" class="form-error" hidden></p>
+    </div>`;
+}
+
+/**
+ * ContactForm — the full form section.
+ */
+function ContactForm() {
+  return `
+    <section class="form-card" aria-labelledby="form-heading">
+      <div class="form-card-header">
+        <h1 id="form-heading" class="form-title">Contact Support</h1>
+        <p class="form-subtitle">We typically respond within 24&nbsp;hours.</p>
+      </div>
+
+      <form id="contact-form" class="form-body" novalidate>
+        <p class="required-legend">
+          Fields marked <span class="req-star" aria-hidden="true">*</span>
+          <span class="sr-only">with an asterisk</span> are required.
+        </p>
+
+        ${TextField({
+          id: "full-name",
+          label: "Full name",
+          required: true,
+          autocomplete: "name",
+        })}
+
+        ${TextField({
+          id: "email",
+          label: "Email address",
+          type: "email",
+          required: true,
+          autocomplete: "email",
+        })}
+
+        ${TextField({
+          id: "phone",
+          label: "Phone number",
+          type: "tel",
+          autocomplete: "tel",
+          helpText: "Include your country code, e.g.\u00a0+1\u00a0555\u00a0000\u00a00000",
+        })}
+
+        <div class="form-actions">
+          <button type="submit" class="btn-submit">Send message</button>
+        </div>
+      </form>
+    </section>`;
+}
+
+/** App — top-level component. */
+function App() {
+  return ContactForm();
+}
+
+/* ─── Utilities ──────────────────────────────────────────── */
+
+function escHtml(str) {
+  return String(str)
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;");
+}
+
+/**
+ * Returns the visible label text for an input (strips hidden marker spans).
+ */
+function labelText(input) {
+  const label = document.querySelector(`label[for="${input.id}"]`);
+  if (!label) return input.id;
+  const clone = label.cloneNode(true);
+  clone.querySelectorAll(".required-mark, .optional-badge").forEach((n) => n.remove());
+  return clone.textContent.trim();
+}
+
+/* ─── Validation ─────────────────────────────────────────── */
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+const TEL_RE   = /^\+?[\d\s\-(). ]{6,}$/;
+
+function validateInput(input) {
+  const errorEl = document.getElementById(`${input.id}-error`);
+  let message = "";
+
+  if (input.required && !input.value.trim()) {
+    message = `Error: ${labelText(input)} is required.`;
+  } else if (input.type === "email" && input.value.trim() && !EMAIL_RE.test(input.value.trim())) {
+    message = "Error: Enter a valid email address, like name@example.com.";
+  } else if (input.type === "tel" && input.value.trim() && !TEL_RE.test(input.value.trim())) {
+    message = "Error: Enter a valid phone number, e.g.\u00a0+1\u00a0555\u00a0000\u00a00000.";
+  }
+
+  if (message) {
+    input.setAttribute("aria-invalid", "true");
+    errorEl.textContent = message;
+    errorEl.removeAttribute("hidden");
+    return false;
+  }
+
+  input.removeAttribute("aria-invalid");
+  errorEl.textContent = "";
+  errorEl.setAttribute("hidden", "");
+  return true;
+}
+
+function clearError(input) {
+  const errorEl = document.getElementById(`${input.id}-error`);
+  input.removeAttribute("aria-invalid");
+  errorEl.textContent = "";
+  errorEl.setAttribute("hidden", "");
+}
+
+/* ─── Mount & wire up ────────────────────────────────────── */
+
+const appEl = document.getElementById("app");
+appEl.innerHTML = App();
+
+const form = document.getElementById("contact-form");
+const statusRegion = document.getElementById("form-status");
+
+/* Validate each field on blur (only if it already has a value or was previously invalid) */
+form.querySelectorAll(".form-input").forEach((input) => {
+  input.addEventListener("blur", () => {
+    /* Only run blur validation if the user has interacted with this field */
+    if (input.value.trim() !== "" || input.getAttribute("aria-invalid") === "true") {
+      validateInput(input);
+    }
+  });
+
+  /* Clear error as soon as the user corrects the field */
+  input.addEventListener("input", () => {
+    if (input.getAttribute("aria-invalid") === "true") {
+      /* Re-validate on each keystroke to give immediate positive feedback */
+      validateInput(input);
+    }
+  });
+});
+
+form.addEventListener("submit", (e) => {
+  e.preventDefault();
+
+  const inputs = Array.from(form.querySelectorAll(".form-input"));
+  const valid  = inputs.map(validateInput);
+  const firstInvalid = inputs.find((_, i) => !valid[i]);
+
+  if (firstInvalid) {
+    /* Move focus to the first invalid field so AT announces its error */
+    firstInvalid.focus();
+    return;
+  }
+
+  /* ── Success ── */
+  /* Replace the form body with a success message */
+  form.closest(".form-card").innerHTML = `
+    <div class="success-state" tabindex="-1" aria-labelledby="success-heading">
+      <div class="success-icon-wrap" aria-hidden="true">
+        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">
+          <circle cx="12" cy="12" r="10"/>
+          <polyline points="9 12 11 14 15 10"/>
+        </svg>
+      </div>
+      <h2 id="success-heading" class="success-title">Message sent!</h2>
+      <p class="success-body">Thanks for reaching out. We'll get back to you within 24&nbsp;hours.</p>
+    </div>`;
+
+  /* Move focus to success panel */
+  document.querySelector(".success-state").focus();
+
+  /* Announce to AT that are not tracking focus (e.g. browse mode) */
+  statusRegion.textContent = "Your message has been sent. We'll get back to you within 24 hours.";
+});
+
')

